  if (!newBatchId) return;

  console.log(
    { itemExternalId, batchId: newBatchId, signupsSelected: signupsToNotify.length },
    "notification batch created",
  );

  // Use workflow.attempt to drive the batch through email dispatch (processing → completed/failed)
  const claimed = await workflow.attempt<NotificationBatchRow, void>(
    "notification_batches",
    newBatchId,
    { from: "processing" },
    async (_row) => {
      // Dispatch emails (respects quiet hours; if in quiet hours, sends are left pending for cron)
      await dispatchBatchEmails(newBatchId as NotificationBatchId, itemExternalId);
    },
  );

  if (!claimed) {
    console.log({ batchId: newBatchId }, "batch already claimed by another worker");
  }

  // Refresh demand stats snapshot regardless of email dispatch outcome
  await refreshDemandStatsSnapshot(itemExternalId, itemType, productExternalId);
}
